#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Status {
    #[default]
    Pending = 0,
    Running = 1,
    Complete = 2,
    Error = 3,
    RetryableError = 4,
}

impl From<Status> for FbsStatus {
    fn from(val: Status) -> Self {
        match val {
            Status::Pending => FbsStatus::Pending,
            Status::Running => FbsStatus::Running,
            Status::Complete => FbsStatus::Complete,
            Status::Error => FbsStatus::Error,
            Status::RetryableError => FbsStatus::RetryableError,
        }
    }
}

impl From<FbsStatus> for Status {
    fn from(fbs: FbsStatus) -> Self {
        match fbs.0 {
            0 => Self::Pending,
            1 => Self::Running,
            2 => Self::Complete,
            3 => Self::Error,
            4 => Self::RetryableError,
            _ => panic!("Invalid value {} when constructing Status", fbs.0)
        }
    }
}

